#!/usr/bin/env python3
"""Check local Qdrant reachability, list collections, print memory counts."""
import os
import sys

from qdrant_client import QdrantClient


def get_host_port():
    try:
        from imprint import config
        return config.QDRANT_HOST, int(config.QDRANT_PORT)
    except Exception:
        # Fallback: same env vars/defaults as imprint/config_schema.py
        return (
            os.environ.get("IMPRINT_QDRANT_HOST", "127.0.0.1"),
            int(os.environ.get("IMPRINT_QDRANT_PORT", "6333")),
        )


def main() -> int:
    host, port = get_host_port()
    print(f"Connecting to Qdrant at {host}:{port} ...")
    client = QdrantClient(host=host, port=port, prefer_grpc=False, timeout=10.0)

    try:
        collections = client.get_collections().collections
    except Exception as e:
        print(f"UNREACHABLE: {type(e).__name__}: {e}")
        return 1

    print("Reachable: OK")
    if not collections:
        print("No collections found.")
        return 0

    print(f"Collections ({len(collections)}):")
    for c in collections:
        try:
            n = client.count(collection_name=c.name, exact=True).count
            print(f"  - {c.name}: {n} memories")
        except Exception as e:
            print(f"  - {c.name}: count failed ({type(e).__name__}: {e})")

    client.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
