#!/usr/bin/env python3
"""Check connectivity to the local Qdrant server and report per-collection counts."""
import os
import sys

from qdrant_client import QdrantClient


def _host_port() -> tuple[str, int]:
    try:
        from imprint import config
        return config.QDRANT_HOST, int(config.QDRANT_PORT)
    except Exception as e:
        print(f"[warn] imprint.config unavailable ({e}); using env/defaults")
        return (
            os.environ.get("IMPRINT_QDRANT_HOST", "127.0.0.1"),
            int(os.environ.get("IMPRINT_QDRANT_PORT", "6333")),
        )


def main() -> int:
    host, port = _host_port()
    print(f"Connecting to Qdrant at {host}:{port} ...")
    # Same construction as imprint/vectorstore.py, but no auto-spawn.
    client = QdrantClient(host=host, port=port, prefer_grpc=False, timeout=10.0)
    try:
        try:
            collections = client.get_collections().collections
        except Exception as e:
            print(f"[FAIL] Qdrant not reachable at {host}:{port}: {e}")
            return 1
        print("[OK] Qdrant is reachable")

        names = [c.name for c in collections]
        print(f"Collections ({len(names)}): {', '.join(names) or '(none)'}")

        total = 0
        for name in names:
            try:
                n = client.count(collection_name=name, exact=True).count
            except Exception as e:
                print(f"  {name}: error counting points ({e})")
                continue
            total += n
            print(f"  {name}: {n} memories")
        print(f"Total: {total}")
        return 0
    finally:
        try:
            client.close()
        except Exception:
            pass


if __name__ == "__main__":
    sys.exit(main())
